void *pool_thread(void *arg) {          /* pool mutex m, condvar cv, int leader */
  for (;;) {
    pthread_mutex_lock(&m);
    while (leader) pthread_cond_wait(&cv, &m);  /* follower */
    leader = 1; pthread_mutex_unlock(&m);       /* become leader */
    int n = epoll_wait(epfd, evs, MAX, -1);     /* demultiplex, unlocked */
    pthread_mutex_lock(&m);
    leader = 0; pthread_cond_signal(&cv);       /* promote a follower */
    pthread_mutex_unlock(&m);
    dispatch(evs, n);                           /* process as ex-leader */
  }
}
